INSERT INTO recipe_step (recipe_id, step_number, instruction, cooking_method_code) VALUES
  ('618b5e9a-f493-5e2f-ba77-65237e6ed38a', 1, 'Brown garlic and chicken in oil.', 'PAN_FRY'),
  ('618b5e9a-f493-5e2f-ba77-65237e6ed38a', 2, 'Add soy sauce, vinegar, bay leaves, pepper; simmer 30 minutes.', 'SIMMER'),
  ('cc1bcbef-cba6-5958-9cdc-dcb785024361', 1, 'Cook rice (ideally a day ahead).', 'RICE_COOK'),
  ('cc1bcbef-cba6-5958-9cdc-dcb785024361', 2, 'Fry garlic until golden, add rice and salt.', 'PAN_FRY'),
  ('3f3c8c71-4bc8-5ade-8404-c52d59e04ca0', 1, 'Stir-fry sliced chicken until cooked.', 'STIR_FRY'),
  ('3f3c8c71-4bc8-5ade-8404-c52d59e04ca0', 2, 'Add broccoli, garlic and soy sauce; toss 3 minutes.', 'STIR_FRY'),
  ('2414c68b-4e81-5fc9-a7c4-6fb030877cab', 1, 'Boil spaghetti.', 'BOIL'),
  ('2414c68b-4e81-5fc9-a7c4-6fb030877cab', 2, 'Soften onion and garlic in oil, add sauce and simmer.', 'SIMMER'),
  ('7dbd1bea-0f12-5ef5-aafd-a09cd7bdad5f', 1, 'Whisk eggs (and milk).', NULL),
  ('7dbd1bea-0f12-5ef5-aafd-a09cd7bdad5f', 2, 'Cook vegetables in butter, add eggs, fold.', 'PAN_FRY'),
  ('f756c54f-3665-5a69-ab3a-74ecff1696b4', 1, 'Brown tofu cubes.', 'STIR_FRY'),
  ('f756c54f-3665-5a69-ab3a-74ecff1696b4', 2, 'Add vegetables, garlic and soy sauce.', 'STIR_FRY'),
  ('ba56a472-78e2-50b1-8134-fd257323c0da', 1, 'Toast bread if you like, spread peanut butter, top with banana.', NULL),
  ('666a5771-bd95-5e1d-9886-77f82b93ee1c', 1, 'Steam fish with ginger 10 minutes.', 'STEAM'),
  ('666a5771-bd95-5e1d-9886-77f82b93ee1c', 2, 'Pour hot garlic oil and soy sauce over.', NULL),
  ('a67b2047-1be9-5ba1-aa27-291a304686e6', 1, 'Saute garlic, onion and ginger.', 'PAN_FRY'),
  ('a67b2047-1be9-5ba1-aa27-291a304686e6', 2, 'Add coconut milk and shrimp; simmer until pink. Season with fish sauce.', 'SIMMER'),
  ('a84a14c8-671b-55c7-aa5f-659668b093b8', 1, 'Toss wedges with oil, salt and pepper; roast at 220C for 35 minutes.', 'ROAST');
